/**
 * Ships and nautical travel (Of Ships and the Sea, owner's request 1.0.80; tables in module/rules/naval-tables.mjs,
 * GENERATED by tools/build-naval-tables.py, which quotes and regex-checks every rule used here). Pure functions; dice are
 * injectable (`roll(formula)` returns a number) so the rules can be tested.
 * Sources (adnd2e.fandom.com): Ship Particulars (OSS) rev 173984 (Tables 1/2: "Small equals 5–19 feet long, Medium equals
 * 20–59 feet long, Large equals 60–100 feet long, and Very Large equals 100+ feet long"; skeleton crews "move at only two
 * thirds of their normal movement rates" with "-2 penalty on all Seaworthiness checks and a -2 penalty to maneuverability
 * and pursuit"; below the minimum "the ship's movement rating falls to 3"), Movement (OSS) rev 173978 (daily movement,
 * speed increases, Tables 3-5, gales and storms), Shipwrecks (OSS) rev 172512 ("If the roll is greater than the
 * Seaworthiness value, the ship either founders or grounds"), Vision (OSS) rev 172711 (Table 6), Encounter Tables (OSS)
 * rev 249009, Resolution Phase (OSS) rev 249023 (Table 28 seaworthiness loss, hull/crippling effects, repairs, Table 30),
 * Fleet Battles (OSS) rev 172688 (Table 38: combat figures, hull and crippling points).
 * Implementation choices (marked where used): Table 2 figures for travel and Table 38 figures for naval combat (the two
 * differ for the great galley and the dromond); a single-rate ship's propulsion (naval-tables.mjs PROPULSION); crippling
 * damage counted in thirds of the crippling points (the fraction is missing in the wiki text); one hit die per sailor,
 * rower and marine unless set on the ship.
 */
import { NAVAL } from "./rules/naval-tables.mjs";

export { NAVAL };
export const SIZES = NAVAL.sizes;
export const EXPERIENCE = NAVAL.combat.crew.map(c => c.key);
export const COURSES = ["with", "across", "into"];
export const WINDS = ["calm", "light", "moderate", "strong", "gale", "storm"];
export const DIRECTIONS = ["north", "east", "south", "west"];

const third = 1 / 3;
const r1 = n => Math.round(n * 10) / 10;

/** The Table 1/2/38 entry of a ship type (or null). */
export function shipType(key) {
  return NAVAL.ships.find(s => s.key === key) ?? null;
}

/** Size category from a length in feet (Table 2 notes). */
export function sizeForLength(feet) {
  const f = Number(feet) || 0;
  if (f > 100) return "veryLarge";
  if (f >= 60) return "large";
  if (f >= 20) return "medium";
  return "small";
}

/**
 * A ship type's figures at a length (the barge, canoe, outrigger and raft footnotes: per step above or below the
 * standard length; pure). Returns a copy with length, beam, cost, crew, passengers, cargo, hull, seaworthiness and size.
 */
export function shipSpec(key, length = null) {
  const base = shipType(key);
  if (!base) return null;
  const s = structuredClone(base);
  const v = s.variable;
  const len = Number(length);
  if (v && Number.isFinite(len) && len > 0 && len !== base.length) {
    const steps = Math.trunc((len - base.length) / v.step);
    s.length = len;
    if (v.beam) s.beam = Math.max(base.beam + steps * v.beam, 1);
    if (v.cost) s.cost = Math.max(base.cost + steps * v.cost, 0);
    if (v.crew) s.crew.max = Math.max(base.crew.max + steps * v.crew, 1);
    if (v.passengers) s.passengers = Math.max(base.passengers + steps * v.passengers, 0);
    if (v.cargoTons) s.cargo = { tons: Math.max((base.cargo.tons ?? 0) + steps * v.cargoTons, 0) };
    if (v.cargoLb) s.cargo = { lb: Math.max((base.cargo.lb ?? 0) + steps * v.cargoLb, 0) };
    if (v.hull) s.combat.hull = s.combat.crippling = Math.max(base.combat.hull + steps * v.hull, 1);
    if (v.marines) s.combat.marines = Math.max(base.combat.marines + steps * v.marines, 0);
    if (v.seaworthinessBelow && steps < 0) {
      s.seaworthiness = Math.max(base.seaworthiness + steps * v.seaworthinessBelow, 1);
      s.combat.seaworthiness = Math.max(base.combat.seaworthiness + steps * v.seaworthinessBelow, 1);
    }
    // "A raft gains a defense class of D if it is at least 30 feet long" (Fleet Battles (OSS)).
    if (key === "raft" && len >= 30) s.combat.defense = "D";
  }
  s.sizeKey = s.size.length > 1 ? sizeForLength(s.length) : s.size[0];
  return s;
}

/** The means of propulsion a ship can use now: the chosen one if the ship has it, else its own. */
export function propulsionOf(spec, chosen = "") {
  if (!spec) return "sail";
  if (spec.propulsion !== "both") return spec.propulsion;
  return ["sail", "oar", "both"].includes(chosen) ? chosen : "both";
}

/** Base movement rate (tens of yards per round) for a propulsion; `combat` = Table 38 figures. */
export function baseRate(spec, propulsion, { combat = false } = {}) {
  const m = combat ? spec.combat.move : spec.move;
  const p = propulsionOf(spec, propulsion);
  return m[p] ?? m.sail ?? m.oar ?? 0;
}

/** Whether the ship moves as a sailing ship ("Any ship moving under sails (even if it has rowers to help) counts as a sailing ship"). */
export const sails = (spec, propulsion) => propulsionOf(spec, propulsion) !== "oar";

/**
 * Table 3: the sailing rate for a wind and course (pure). null for a calm (sailing ships do not move), 0 into a strong
 * wind (NM); into a gale or storm: backwards at a third of the base rate (a negative rate).
 */
export function sailingRate(base, wind, course) {
  if (wind === "calm") return 0;
  if ((wind === "gale" || wind === "storm") && course === "into") return -base * third;
  const mod = NAVAL.wind[wind]?.[course];
  if (mod === null) return 0;
  return base + base * (mod ?? 0);
}

/** Crew state from the counts aboard (pure): "full", "skeleton" (below average, at least the minimum) or "below". */
export function crewState(spec, count) {
  const n = Number(count) || 0;
  if (n < spec.crew.minimum) return "below";
  if (n < spec.crew.average) return "skeleton";
  return "full";
}

/** Thirds of hull points lost that count (Resolution Phase (OSS)): 1 at half lost, 2 at three quarters. */
export function hullSteps(hull, max) {
  const lost = Math.max((max ?? 0) - (hull ?? 0), 0);
  if (!max) return 0;
  if (lost >= max * 0.75) return 2;
  if (lost >= max / 2) return 1;
  return 0;
}

/** Thirds of crippling points lost (implementation choice: the fraction is missing in the source text). */
export function cripplingSteps(value, max) {
  if (!max) return 0;
  const lost = Math.max(max - (value ?? 0), 0);
  return Math.min(Math.floor(lost / (max / 3) + 1e-9), 3);
}

/** Maneuverability penalty from damage (pure): -2 / -3 for hull, -2 per crippling third. */
export function damageDiceMod(ship) {
  const h = hullSteps(ship.hull, ship.hullMax);
  return (h === 1 ? -2 : h === 2 ? -3 : 0) - 2 * cripplingSteps(ship.crippling, ship.cripplingMax);
}

/**
 * Table 28 (pure): seaworthiness lost for the hull points lost ("Medium ships lose two points of Seaworthiness for every
 * three hull points lost").
 */
export function seaworthinessLoss(sizeKey, hullLost) {
  const [pts, per] = NAVAL.combat.seaworthinessLoss[sizeKey] ?? [0, 1];
  return Math.floor(Math.max(hullLost, 0) / per) * pts;
}

/** Current seaworthiness rating (pure): the type's (or the ship's own) less the Table 28 loss; never below 1. */
export function seaworthinessNow(base, sizeKey, hullLost) {
  return Math.max(base - seaworthinessLoss(sizeKey, hullLost), 1);
}

/**
 * Movement rate now (pure): base rate (Table 2 for travel, Table 38 in combat), the wind for sailing ships, then crew
 * (skeleton 2/3, below the minimum 3), damage (hull 1/3 at half lost, 2/3 at three quarters; 1/3 per crippling third),
 * resting rowers 1/3. Returns { rate, base, notes[] }; a negative rate = blown backwards (into a gale).
 */
export function currentRate(ship, { wind = "moderate", course = "across", combat = false } = {}) {
  const spec = ship.spec;
  const prop = propulsionOf(spec, ship.propulsion);
  const base = baseRate(spec, prop, { combat });
  const notes = [];
  let rate = sails(spec, prop) ? sailingRate(base, wind, course) : base;
  if (sails(spec, prop) && wind === "calm") notes.push("calm");
  if (ship.crewState === "below") return { rate: Math.min(rate, NAVAL.travel.belowMinimum.move), base, notes: [...notes, "belowMinimum"] };
  if (ship.crewState === "skeleton" && !ship.skeletonPushed) { rate *= NAVAL.travel.skeleton.rate; notes.push("skeleton"); }
  if (ship.restingRowers && prop !== "sail") { rate = Math.min(rate, base * NAVAL.travel.resting); notes.push("resting"); }
  const cut = third * (hullSteps(ship.hull, ship.hullMax) + cripplingSteps(ship.crippling, ship.cripplingMax));
  if (cut > 0) { rate = rate > 0 ? Math.max(rate - base * cut, 0) : rate; notes.push("damage"); }
  return { rate: r1(rate), base, notes };
}

/**
 * Daily movement in miles (pure; Movement (OSS)): rowed ships twice the rate, sailing ships three times sailing through
 * the night, twice when anchoring; a successful push +1/3. Into a gale or storm: backwards at a third of the base rate a
 * day (0 with a Seamanship check; not in a storm).
 */
export function dailyMiles(rate, { rowing = false, anchor = false, push = false } = {}) {
  const factor = rowing ? NAVAL.travel.rowMilesPerRate : anchor ? NAVAL.travel.anchorMilesPerRate : NAVAL.travel.sailMilesPerRate;
  let miles = rate * factor;
  if (push && miles > 0) miles += miles * NAVAL.travel.push.fraction;
  return r1(miles);
}

/**
 * Gale or storm drift (pure): across or with the wind, the ship is also pushed an equal distance with the wind; a
 * Seamanship check in a gale cuts it by a third; into the wind the day's movement is backwards (0 with Seamanship in a gale).
 */
export function galeDrift(miles, wind, course, { seamanship = false } = {}) {
  if (wind !== "gale" && wind !== "storm") return { forward: miles, drift: 0 };
  const allowed = wind === "gale" && seamanship;
  if (course === "into") return { forward: allowed ? 0 : miles, drift: 0 };
  const drift = Math.abs(miles) * (allowed ? NAVAL.gale.seamanshipDrift : NAVAL.gale.drift);
  return { forward: miles, drift: r1(drift) };
}

/** Course relative to the wind (pure): the wind blows FROM `windFrom`; sailing toward it is "into". */
export function courseFor(heading, windFrom) {
  const i = DIRECTIONS.indexOf(heading);
  const j = DIRECTIONS.indexOf(windFrom);
  if (i < 0 || j < 0) return "across";
  if (i === j) return "into";
  if ((i + 2) % 4 === j) return "with";
  return "across";
}

/** Table 4: wind for a 2d6 (or next-day) total, clamped to 2-12 (pure). */
export function windFor(total) {
  const t = Math.min(Math.max(Math.round(total), 2), 12);
  return NAVAL.windStrength.find(w => w.roll === t);
}

/** Table 5: wind direction for a 2d6 total and season (pure). */
export function directionFor(total, season) {
  const t = Math.min(Math.max(Math.round(total), 2), 12);
  const row = NAVAL.windDirection.find(w => w.roll === t);
  return ["fall", "winter"].includes(season) ? row.cold : row.warm;
}

/**
 * A day's wind (pure over `roll`, which may be async): the previous state { wind, next, daysLeft, direction, directionDays }. When the
 * next-day dice have run out (or on the first day) roll 2d6 and 1d4 days; the direction holds 1d4 days, then Table 5.
 */
export async function nextWind(prev, season, roll) {
  const state = { ...(prev ?? {}) };
  const fresh = !state.wind || !(state.daysLeft > 0);
  const total = await roll(fresh ? "2d6" : state.next || "2d6");
  const row = windFor(total);
  state.wind = row.wind;
  // The first day's roll sets the next-day dice "every day for 1d4 days"; those days then count down.
  if (fresh) { state.next = row.next; state.daysLeft = await roll(NAVAL.windDays); }
  else state.daysLeft = Math.max((state.daysLeft ?? 1) - 1, 0);
  state.roll = total;
  if (!state.direction || !(state.directionDays > 0)) {
    state.direction = directionFor(await roll("2d6"), season);
    state.directionDays = await roll(NAVAL.windDays);
  }
  state.directionDays = Math.max((state.directionDays ?? 1) - 1, 0);
  return state;
}

/**
 * A seaworthiness check (pure): d20 against the rating with penalties (storm -3, skeleton crew -2, jury-rigged -3, others);
 * fails when the roll is greater than the adjusted rating. A natural 20 in a storm capsizes; on rocks it splinters.
 */
export function seaworthinessCheck(d20, rating, { penalty = 0, storm = false, rocky = false } = {}) {
  const target = rating + penalty;
  const fail = d20 > target;
  return { roll: d20, target, fail, capsized: fail && storm && d20 === 20, splintered: fail && rocky && d20 === 20 };
}

/** Penalties for a seaworthiness check (pure): storm -3, skeleton crew -2 (unless pushed), jury-rigged -3, other. */
export function checkPenalty({ wind = "", skeleton = false, jury = false, extra = 0 } = {}) {
  return (wind === "storm" ? NAVAL.storm.checkPenalty : 0) + (skeleton ? NAVAL.travel.skeleton.seaworthiness : 0)
    + (jury ? NAVAL.wreck.juryPenalty : 0) + (Number(extra) || 0);
}

/** A speed increase roll (pure): d20 + 3 with a successful Seamanship check, 12 or better (daily push: check at -2). */
export const boostSucceeds = (d20, seamanship = false) => d20 + (seamanship ? NAVAL.travel.boost.seamanship : 0) >= NAVAL.travel.boost.target;

/** Rowing a small craft (pure): hours before Constitution checks = half the Constitution, rounded up. */
export const rowingHours = con => Math.ceil((Number(con) || 0) * NAVAL.travel.smallCraft.hoursPerCon);

/**
 * Table 6 (pure): the ranges in yards for a condition, the target ship's size and the viewer's height; land features use
 * their own multiplier. Size and height multipliers do not apply to Detail, height not to ID.
 */
export function visibility(condition, { size = "small", height = "deck", land = null } = {}) {
  const row = NAVAL.vision.find(v => v.key === condition) ?? NAVAL.vision[0];
  const s = land ? NAVAL.visionLand[land] ?? 1 : NAVAL.visionSize[size] ?? 1;
  const h = NAVAL.visionHeight[height] ?? 1;
  return { movement: row.movement * s * h, spotted: row.spotted * s * h, type: row.type * s * h, id: row.id * s, detail: row.detail, label: row.label };
}

/** Encounter checks for a day in an area (pure over `roll`): [{ check, roll, hit, result }]. */
export async function encounterChecks(area, roll) {
  const a = NAVAL.encounters[area];
  if (!a) return [];
  const out = [];
  for (let i = 1; i <= a.checks; i++) {
    const d6 = await roll("1d6");
    const hit = d6 <= a.chance;
    let result = null;
    if (hit) {
      const total = (await roll("1d8")) + (await roll("1d12"));
      result = a.rows.find(r => r.roll === total) ?? null;
      if (result && /Natural Phenomen/.test(result.label)) {
        const t2 = (await roll("1d8")) + (await roll("1d12"));
        result = { ...result, phenomenon: NAVAL.encounters.phenomena.find(r => r.roll === t2) ?? null };
      }
    }
    out.push({ check: i, roll: d6, hit, result });
  }
  return out;
}

/** Natural phenomenon label for an area: "A (coastline)/B (sea)" entries pick the matching part (pure). */
export function phenomenonLabel(label, coast) {
  const m = String(label).match(/^(.*?)\s*\((coast|coastline)\)\s*(?:\/|or)\s*(.*?)\s*\(sea\)$/);
  if (m) return coast ? m[1] : m[3];
  return label;
}

/** Table 30 (pure): shipyard repair cost (gp) and days for points of hull and crippling damage. */
export function shipyardRepair(sizeKey, points) {
  const r = NAVAL.combat.repairs[sizeKey] ?? NAVAL.combat.repairs.small;
  const p = Math.max(Number(points) || 0, 0);
  return { cost: p * r.cost, days: Math.ceil(p / r.points) * r.days };
}

/** Repair at sea (pure): at most 1d6 hull and 1d12 crippling points, never more than the event caused. */
export function seaRepair({ hullRoll, cripplingRoll, hullLost, cripplingLost }) {
  return { hull: Math.min(hullRoll, Math.max(hullLost, 0)), crippling: Math.min(cripplingRoll, Math.max(cripplingLost, 0)) };
}

/** Days a repair at sea takes (pure): hull 1d4 + 2 per size above Small; crippling 1d4. */
export const seaRepairDays = (sizeKey, d4) => d4 + 2 * Math.max(SIZES.indexOf(sizeKey), 0);

/** Table 31 base morale for a crew experience (pure). */
export const baseMorale = experience => NAVAL.combat.morale[experience] ?? NAVAL.combat.morale.mates;

/** Table 12: crew experience for a 3d4 total (+2 traders and pirates, +3 privateers and warships; pure). */
export function experienceFor(total) {
  return NAVAL.combat.crew.find(c => (c.range[0] === null || total >= c.range[0]) && (c.range[1] === null || total <= c.range[1]))?.key
    ?? (total < 3 ? "landlubbers" : "oldSalts");
}

/** Crew maneuverability/pursuit modifier for an experience (Table 12; pure). */
export const experienceMod = experience => NAVAL.combat.crew.find(c => c.key === experience)?.mod ?? 0;

/** "1d6+4" text for a dice spec { n, die, plus } with an extra modifier (pure). */
export function diceText(d, extra = 0) {
  const plus = (d?.plus ?? 0) + (extra || 0);
  return `${d?.n ?? 1}d${d?.die ?? 6}${plus > 0 ? `+${plus}` : plus < 0 ? plus : ""}`;
}

/**
 * Pursuit dice for a movement rate (Table 2 notes: "1d6 plus one third of its current movment rating"; pure). Below the
 * minimum crew a ship "cannot make pursuit rolls (effectively it always rolls a one)".
 */
export function pursuitDice(rate, crew = "full") {
  if (crew === "below") return { n: 0, die: 1, plus: 1 };
  return { n: 1, die: 6, plus: Math.floor(Math.max(rate, 0) / 3) };
}

/** Maneuverability dice for the propulsion (Table 38 in combat; below the minimum crew 1d4; pure). */
export function maneuverDice(spec, propulsion, crew = "full") {
  if (crew === "below") return { ...NAVAL.travel.belowMinimum.maneuver };
  const p = propulsionOf(spec, propulsion);
  const m = spec.combat.maneuver;
  return { ...(p === "oar" ? m.oar : m.sail) };
}

/** Deck space for artillery (pure): one unit per undamaged hull point, classes A-C only. */
export function deckSpace(spec) {
  return ["A", "B", "C"].includes(spec.combat.defense) ? spec.combat.hull : 0;
}

/** Artillery weapons' deck space and cargo tons used (pure). */
export function artilleryLoad(pieces) {
  let space = 0;
  let tons = 0;
  for (const p of pieces ?? []) {
    const a = NAVAL.combat.artillery.find(x => x.key === p.key);
    if (!a) continue;
    space += a.space ?? 0;
    tons += a.tons ?? 0;
  }
  return { space, tons };
}

/** Artillery mounting problems (pure): no deck, not enough space or cargo, greek fire limits, trebuchets. */
export function artilleryIssues(spec, pieces) {
  const issues = [];
  const deck = deckSpace(spec);
  const load = artilleryLoad(pieces);
  if (!deck && (pieces ?? []).length) issues.push("noDeck");
  if (deck && load.space > deck) issues.push("space");
  const cargo = spec.cargo?.tons ?? 0;
  if (load.tons > cargo && spec.key !== "trireme") issues.push("cargo");
  if (spec.key === "trireme" && (load.tons > 30 || (pieces ?? []).some(p => (NAVAL.combat.artillery.find(a => a.key === p.key)?.space ?? 0) > 15))) issues.push("trireme");
  const greek = (pieces ?? []).filter(p => p.key === "greekFireProjector").length;
  const greekMax = spec.sizeKey === "small" || spec.combat.hull < 10 ? 0 : spec.sizeKey === "medium" ? 1 : 2;
  if (greek > greekMax) issues.push("greekFire");
  if ((pieces ?? []).some(p => p.key === "trebuchet")) issues.push("trebuchet");
  return issues;
}

/** Crew experience after untrained crewmen replace part of the crew (pure): one step down per quarter (rounded up). */
export function experienceAfterReplacement(experience, crew, untrained) {
  if (!(crew > 0) || !(untrained > 0)) return experience;
  const steps = Math.floor(untrained / Math.ceil(crew / 4));
  const i = Math.max(EXPERIENCE.indexOf(experience) - steps, 0);
  return EXPERIENCE[i];
}
